Lemma rdn_of_defined (M : word -> option byte) : forall (k : nat) (a : Z),
  0 <= a -> a + Z.of_nat k <= 2 ^ 64 -> L5.defined M a (Z.of_nat k) ->
  exists bs, rdn segs M (Z_to_bv 64 a) k = Some bs /\ length bs = k.
Proof.
