Lemma mvec_push M M' v b k stk c :
  PQM.mvec_at segs PMSP.T3 PMSP.T4 M v b k stk -> Z.of_nat (length stk) < 2 ^ k ->
  0 <= v -> v + 24 <= 2 ^ 64 -> 0 <= b -> b + 24 * 2 ^ k <= 2 ^ 64 ->
  L5C.agree_on M M' v 8 -> L5C.agree_on M M' (v + 16) 8 -> L5C.agree_on M M' b (24 * Z.of_nat (length stk)) ->
  L5.defined M' b (24 * 2 ^ k) ->
  L5.u64_at segs M' (v + 8) (b + 24 * Z.of_nat (length stk) + 24) ->
  PQM.mstate_at segs M' (b + 24 * Z.of_nat (length stk)) c ->
