(* [comment removed for export] *)
Lemma mvec_grow M M' v b k stk c B :
  PQM.mvec_at segs PMSP.T3 PMSP.T4 M v b k stk -> Z.of_nat (length stk) = 2 ^ k -> k <= 10 ->
  0 <= b -> b + 24 * 2 ^ k <= 2 ^ 64 -> 0 <= B -> B + 24 * 2 ^ (k + 1) <= 2 ^ 64 -> B mod 16 = 0 ->
  L5.u64_at segs M' v B -> L5.u64_at segs M' (v + 8) (B + 24 * 2 ^ k + 24) -> L5.u64_at segs M' (v + 16) (B + 24 * 2 ^ (k + 1)) ->
  L5.defined M' B (24 * 2 ^ (k + 1)) ->
  (forall i, 0 <= i < 24 * 2 ^ k -> M' (Z_to_bv 64 (B + i)) = M (Z_to_bv 64 (b + i))) ->
  PQM.mstate_at segs M' (B + 24 * 2 ^ k) c ->
