(* [comment removed for export] *)
Lemma mparser_upd M M' op ois s m' d' b' k' stk' :
  PQM.mparser_at segs A PMSP.T3 PMSP.T4 vp M op ois s -> 0 <= op -> op + 400 <= 2 ^ 64 ->
  L5C.agree_on M M' op 8 -> L5C.agree_on M M' (op + 9) 3 -> L5C.agree_on M M' (op + 16) 360 ->
  PQMF.dkr M M' (op + 8) 8 -> PQMF.dkr M M' (op + 376) 24 ->
  L5.u8_at segs M' (op + 8) m' -> (m' = 0 \/ m' = 1) -> L5.u32_at segs M' (op + 12) d' -> 0 <= d' <= PQM.MAX_DEPTH + 1 ->
  PQM.mvec_at segs PMSP.T3 PMSP.T4 M' (op + 376) b' k' stk' ->
  PQMF.dkr M M' (PM.sr_qc (PQM.p_src s)) PM.CHUNK ->
  (forall c n p, PQM.p_tb s = PM.VLong c n p -> PQMF.dkr M M' p c) ->
  (forall b n c, PQM.p_bb s = PQV8.V8Blk b n c -> PQMF.dkr M M' b c) ->
  PQM.mparser_at segs A PMSP.T3 PMSP.T4 vp M' op ois
