(* [comment removed for export] *)
Lemma mgrow_credit L cr0 cr P0 s s' st :
  PMSP.credit_keep cr0 cr P0 (PQM.pot_run L s st) -> PQM.p_sk s' = PQM.p_sk s + 1 -> PQM.p_tb s' = PQM.p_tb s -> PQM.p_tg s' = PQM.p_tg s ->
  PQM.p_bb s' = PQM.p_bb s -> PQM.p_bg s' = PQM.p_bg s -> 0 <= PQM.p_sk s ->
