Definition pb_specC (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (o c sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    hi_heap HI (PM.vs_own x ++ LB) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    WD.entry_scr A L R M sp r WD.PB_SCR ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 c -> 0 <= c < 256 ->
    kstr_at M o x -> kcontent M o x bs -> PQM.ks_ok SM x g -> SM <= PQAS.SMMAX -> PM.vs_size x < SM -> sp <= o -> o + 24 <= hl_sptop L -> o mod 8 = 0 ->
    PMSP.credit_le (PQM.pot_ks L SM x g) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> kcontent M' o x' (bs ++ [c]) -> PQM.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + 1 ->
        L5C.hpres L LB sp WD.PB_SCR [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PQM.pot_ks L SM x g) (PQM.pot_ks L SM x' g') ->
        model_but_vm model model' -> hi_heap HI (PM.vs_own x' ++ LB) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSP.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
Definition GB_SCR : Z := 14272.   (* [comment removed for export] *)
Definition gb_specC (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (cr : credit) (o need sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    hi_heap HI (PM.vs_own x ++ LB) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] ->
    getr R 1%bv = Z_to_bv 64 r -> L5.ra_ok r -> getr R 2%bv = Z_to_bv 64 sp -> getr R 4%bv = Z_to_bv 64 (pa_tp A) ->
    L5C.stk (hl_sptop L) M sp GB_SCR ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 (PM.vs_cap x) -> getr R 12%bv = Z_to_bv 64 (need - PM.vs_cap x) ->
    getr R 13%bv = Z_to_bv 64 (PM.vs_size x) -> getr R 14%bv = Z_to_bv 64 (PM.vs_size x) -> getr R 15%bv = Z_to_bv 64 0 ->
    kstr_at M o x -> kcontent M o x bs -> PQM.ks_ok SM x g -> SM <= PQAS.SMMAX -> PM.vs_cap x < need <= SM ->
    sp <= o -> o + 24 <= hl_sptop L -> o mod 8 = 0 ->
    PMSP.credit_le (PQM.pot_ks L SM x g) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (B Acnt : Z) (cr' : credit),
        regs_preserved R R' -> Acnt = PQAS.gcount (PM.vs_cap x) need ->
        L5.defined M' o 24 -> L5.u64_at segs M' o (Acnt + 1) -> L5.u64_at segs M' (o + 16) B ->
        L5.defined M' B Acnt -> L5.bytes_at segs M' B bs -> 4096 <= B -> B + Acnt <= hl_ceil L ->
        PQM.ks_ok SM (PM.VLong Acnt need B) (g + 1) -> need < Acnt -> 26 <= Acnt <= PQM.KCAP -> Acnt mod 8 = 0 ->
        L5C.hpres L LB sp GB_SCR [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PQM.pot_ks L SM x g) (PQM.pot_ks L SM (PM.VLong Acnt need B) (g + 1)) ->
        model_but_vm model model' -> hi_heap HI ((B, Acnt) :: LB) cr' M' (m_vmmaps model') ->
        srealizes segs SCFG (@PMSP.cfg segs fx' R' r M' model') K) ->
    srealizes segs SCFG (@PMSP.cfg segs fx R pc M model) K.

(* [comment removed for export] *)
Definition src_okC (M : word -> option byte) (LB : list (Z * Z)) (sp o q n : Z) (sbs : list Z) : Prop :=
  0 <= q /\ q + n < 2 ^ 47 /\ (forall i, 0 <= i < n -> L5C.kept L LB sp WD.PB_SCR [(o, 24)] (q + i))
  /\ Z.of_nat (length sbs) = n /\ L5.bytes_at segs M q sbs /\ NEM.bytes_ok sbs.

Lemma src_okC_ok M LB sp o q n sbs : src_okC M LB sp o q n sbs -> PQAS.src_ok segs L M LB sp o q n.
Proof.
  intros (Q0 & Q1 & KP & LEN & BA & BOK). split; [exact Q0|]. split; [exact Q1|]. split; [exact KP|].
  exists (map (fun z => Z_to_bv 8 z) sbs). rewrite length_map. split; [lia|].
  apply (L5C.bytes_at_rdn segs M sbs q Q0 ltac:(lia) BA).
Qed.

