Section ME.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Import PMS. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation st fx R pc M := (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)).
Lemma memmove_runC (fx : FPState) R M (dst src n r : Z) (bs : list Z) :
  getr R (reg 10) = Z_to_bv 64 dst -> getr R (reg 11) = Z_to_bv 64 src -> getr R (reg 12) = Z_to_bv 64 n ->
  getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r ->
  1 <= n -> 0 <= dst -> dst + n < 2 ^ 63 -> 0 <= src -> src + n < 2 ^ 63 -> (dst + n <= src \/ src + n <= dst) ->
  L5.writable RSEGS M dst n -> L5.defined M src n -> L5.bytes_at RSEGS M src bs -> Z.of_nat (length bs) = n ->
  exists R3 M3, msteps RSEGS (st fx R 0xb9d7c M) (st fx R3 r M3)
    /\ mem_grows M M3
    /\ (forall a, 0 <= a < 2 ^ 64 -> ~ (dst <= a < dst + n) -> M3 (Z_to_bv 64 a) = M (Z_to_bv 64 a))
    /\ L5.defined M3 dst n /\ L5.bytes_at RSEGS M3 dst bs
    /\ (forall i, In i L5K.CS -> getr R3 (reg i) = getr R (reg i)) /\ getr R3 (reg 10) = Z_to_bv 64 dst.
Proof.
  intros H10 H11 H12 H1 RA Hn Hd Hdn Hs Hsn AP W D BA LEN.
  destruct (PQBK.copy_run_eq RSEGS 0xb9d7c (fun fx => @PMCPS.memmove_disjoint fx) fx R M dst src n r H10 H11 H12 H1 RA Hn Hd Hdn Hs Hsn AP W D)
    as (R3 & M3 & MS & MG & FR & D3 & CP & KS & A10).
  exists R3, M3. split; [exact MS|]. split; [exact MG|]. split; [exact FR|]. split; [exact D3|]. split; [| split; [exact KS| exact A10]].
  intros i Hi. apply (PQBK.u8_copy RSEGS M M3 (src + Z.of_nat i) (dst + Z.of_nat i)); [lia|lia|lia|lia| | | apply BA; exact Hi].
  - intros j Hj. replace (src + Z.of_nat i + j) with (src + (Z.of_nat i + j)) by lia. apply D. lia.
  - intros j Hj. replace (dst + Z.of_nat i + j) with (dst + (Z.of_nat i + j)) by lia. replace (src + Z.of_nat i + j) with (src + (Z.of_nat i + j)) by lia. apply CP. lia.
Qed.
